import { look, own, person, type HeroStory } from './kit';

// Wren, "The Pack". A hunter raised by Hunter Garrick and by a wolf pack. The night the star fell, the shadow took the
// pack and ran them east; only young Fenn stayed. Snowmoon, the pack's mother, pulled the worst of the shadow into
// herself and ran ahead of it, so it would follow her and not her pups.
//
// Umbra's shadow wears the shape of what each hero fears most, and Wren fears the wild turning on her, and the people
// turning on the wild. Every step of her story is a tracker's: she reads trails, pulls snares, herds, digs, and walks
// frightened beasts home.
//
// Meadow: Wren reads the night in the Old Stone Garden (Snowmoon was holding the shadow back, not leading it), pulls up
// a poacher's snares and runs the poacher, Burr, to ground. Garrick sends her for Thistle, caught in a box-trap; Thistle
// digs up the sun-crystal she carried off the Rise, the villages blame the wolves for what Gorehide the Boar King does,
// and Wren brings back a bristle as proof. Burr's truffles lure the Boar King, and Rotwood's fallen logs rebuild the bridge.
// Woods: Snowmoon's hidden pup Snowpaw, the Bellkeeper's warning, the pack's den in the Root Ruins with a rune and a
// caged scout, the glade's memory of a white wolf curled round a baby, a rune under Snowpaw's den, and the last one where
// Duskmane sleeps: an empty coat of shadow. Moon runes, moon-owl arrows, and Thessaly's torches burn the thorn wall.
// Summit: the starving Summit wolves herded by Starhorn, the stag the shadow hooked through his stolen fawn. Kiri's
// "falling star", Brun's fold, the fawn in the Rift, Hazel under the rubble, and Frostling walked home to the black ice.
// Ember: Snowmoon's bloody trail to Hessa's kiln, salt and a soot-sprite's hoard, the worm's tunnels, Burr and Zara,
// the Last Green, the Phoenix Spring, the forge's vents that drive the Duneworm up, and Umbra, the Moon-Eater. Across the
// four lands, people learn the wolves were never the dark, and Wren learns to stand between both.

const q = own('wren');

const BURR = person('Burr the Poacher', '🪤', { robe: '#5a5a3a', hat: 'cap', hatColor: '#3a3a24', beard: true });
const BURR_LOOK = look('#5a5a3a', 'cap', { hatColor: '#3a3a24', beard: true });
const HESSA_LOOK = look('#b0643a', 'bonnet', { hatColor: '#6a3a2a', hair: '#e8e2d0' });
const wolf = (name: string, fur: string) => person(name, '🐺', { robe: fur, hair: fur });
const FAWN = person('Frostling', '🦌', { robe: '#f4efe6', hat: 'ears', hatColor: '#e8e2d0', skin: '#e8dcc8', hair: '#e8e2d0', small: true });
const BRIONY = person('Scout Briony', '💂‍♀️', { robe: '#6a7a8a', hat: 'helm', hatColor: '#8a8f9a', hair: '#b8743c' });
const CINDERFINCH = person('Cinderfinch', '🔥', { robe: '#3a2e2c', hair: '#1a1210', skin: '#9a8a80', small: true });

