    woods: ['wren50', 'wren3', 'wren4', 'wren13', 'wren52', 'wren53', 'wren54', 'wren14', 'wren55', 'wren56', 'wren16', 'wren57', 'wren58', 'wren19', 'wren59', 'm15', 'wren18', 'wren60'],
    summit: ['wren70', 'wren5', 'wren71', 'wren20', 'wren21', 'wren72', 'wren25', 'wren24', 'wren73', 'wren22', 'wren74', 'wren23', 'm19', 'wren75'],
    ember: ['wren80', 'wren81', 'wren82', 'wren83', 'wren85', 'wren33', 'wren84', 'wren28', 'wren86', 'wren29', 'wren87', 'wren6', 'wren30', 'wren32', 'wren88', 'm12', 'm13'],
